// ===================================
// Slack Event Deduplication - Race Condition Safe
// ===================================

const body = $input.item.json.body;

// 1. URL Verification (Slack setup)
if (body.type === 'url_verification') {
  return [{
    json: { challenge: body.challenge },
    pairedItem: { item: 0 }
  }];
}

// 2. Event Deduplication with Atomic Check-and-Set
const EVENT_CACHE_KEY = 'processed_slack_events_v2';
const EVENT_CACHE_TTL = 300000; // 5 minutes

// Get workflow static data
let workflowData = $getWorkflowStaticData('global');
let processedEvents = workflowData[EVENT_CACHE_KEY] || {};
const currentTime = Date.now();

// Clean expired entries
Object.keys(processedEvents).forEach(eventId => {
  if (currentTime - processedEvents[eventId].timestamp > EVENT_CACHE_TTL) {
    delete processedEvents[eventId];
  }
});

// 3. Handle app_mention events only
if (body.type === 'event_callback' && body.event?.type === 'app_mention') {
  const event = body.event;
  const eventId = body.event_id;

  // CRITICAL: Check for duplicate BEFORE any processing
  if (processedEvents[eventId]) {
    const retryCount = processedEvents[eventId].retries || 0;
    console.log(`🚫 DUPLICATE DETECTED: ${eventId} (Retry #${retryCount + 1})`);

    // Update retry count for monitoring
    processedEvents[eventId].retries = retryCount + 1;
    processedEvents[eventId].lastRetry = currentTime;
    workflowData[EVENT_CACHE_KEY] = processedEvents;

    // Return empty array to stop workflow execution
    return [];
  }

  // 4. Mark as processed IMMEDIATELY (before any processing)
  processedEvents[eventId] = {
    timestamp: currentTime,
    retries: 0,
    query: event.text.replace(/<@\w+>/g, '').trim()
  };
  workflowData[EVENT_CACHE_KEY] = processedEvents;

  // 5. Extract clean query
  const query = event.text.replace(/<@U09LPC5D2U8>/g, '').trim();

  // 6. Return event data for AI processing
  return [{
    json: {
      query: query,
      channel: event.channel,
      user: event.user,
      thread_ts: event.ts,
      team_id: body.team_id,
      event_id: eventId,
      timestamp: currentTime
    },
    pairedItem: { item: 0 }
  }];
}

// 7. Ignore all other event types
console.log(`ℹ️ Ignored event type: ${body.event?.type || body.type}`);
return [];

// ===================================
// Enhanced Slack Formatter - With Rich Document Details
// ===================================

const data = $input.item.json;
const query = data.query || $('Process Event1').item.json.query || 'Your question';
const aiOutput = (data.output || data.text || '').trim();
const searchResults = data.search_results || [];
const channel = data.channel || $('Process Event1').item.json.channel;
const thread_ts = data.thread_ts || $('Process Event1').item.json.thread_ts;

// Debug logging
console.log('📝 Formatter received:', {
  has_channel: !!channel,
  channel_value: channel,
  has_thread_ts: !!thread_ts,
  has_search_results: searchResults.length,
  query_preview: query?.substring(0, 50)
});

// Clean AI output
const cleanAI = aiOutput
  .replace(/\[thinking\][\s\S]*?\[\/thinking\]/gi, '')
  .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
  .replace(/^>.*$/gm, '')
  .trim();

// Build Slack blocks
const blocks = [];

// Header
blocks.push({
  "type": "header",
  "text": {
    "type": "plain_text",
    "text": "🤖 Nomi BMS Assistant",
    "emoji": true
  }
});

// Question
blocks.push({
  "type": "section",
  "text": {
    "type": "mrkdwn",
    "text": `*Question*\n${query}`
  }
});

blocks.push({"type": "divider"});

// Answer (keep concise)
const answer = cleanAI.length > 2500 ? cleanAI.substring(0, 2500) + '...' : cleanAI;
blocks.push({
  "type": "section",
  "text": {
    "type": "mrkdwn",
    "text": answer
  }
});

// ===================================
// Rich Document Details
// ===================================
if (searchResults.length > 0) {
  blocks.push({"type": "divider"});

  blocks.push({
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*📚 Source Documents* (${searchResults.length} results)`
    }
  });

  // Show each document with rich metadata
  searchResults.forEach((doc, i) => {
    const name = doc.document_name || 'Unknown Document';
    const score = doc.score ? (parseFloat(doc.score) * 100).toFixed(1) : 'N/A';
    const content = (doc.content || doc.text || '').substring(0, 200).trim();
    const url = doc.document_url || doc.metadata?.document_url || '';

    // Metadata
    const type = doc.document_type || doc.metadata?.document_type || '';
    const dept = doc.department || doc.metadata?.department || '';

    // Keywords/Entities
    let keywords = [];
    let entities = [];
    let technicalTerms = [];

    try {
      // Parse JSON strings or use arrays directly
      const parseField = (field) => {
        if (!field) return [];
        if (Array.isArray(field)) return field;
        if (typeof field === 'string') return JSON.parse(field);
        return [];
      };

      keywords = parseField(doc.keywords || doc.metadata?.keywords);
      entities = parseField(doc.entities || doc.metadata?.entities);
      technicalTerms = parseField(doc.technical_terms || doc.metadata?.technical_terms);
    } catch (e) {
      // Ignore parse errors
    }

    // Combine and deduplicate terms
    const allTerms = [...keywords, ...entities, ...technicalTerms]
      .filter(t => t && typeof t === 'string' && t.length > 0)
      .filter(t => !t.match(/^\d+$/)); // Remove pure numbers

    const uniqueTerms = [...new Set(allTerms)].slice(0, 5);

    // Build document text
    let docText = `*${i + 1}. `;

    // Add clickable link if URL available
    if (url) {
      docText += `<${url}|${name}>*\n`;
    } else {
      docText += `${name}*\n`;
    }

    // Metadata line
    let meta = `Score: ${score}%`;
    if (type) meta += ` • Type: ${type}`;
    if (dept) meta += ` • Dept: ${dept}`;
    docText += `${meta}\n`;

    // Keywords line
    if (uniqueTerms.length > 0) {
      docText += `_Keywords: ${uniqueTerms.join(', ')}_\n`;
    }

    // Content preview
    docText += `\n> ${content}${content.length >= 200 ? '...' : ''}`;

    blocks.push({
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": docText
      }
    });
  });
} else {
  // Fallback: Extract and show document IDs from AI response
  const docIds = [...new Set((cleanAI.match(/BMS[\-\u2011][A-Z]+[\-\u2011][A-Z]+[\-\u2011]\d+/g) || []))];

  if (docIds.length > 0) {
    blocks.push({"type": "divider"});

    let refs = `*📚 Referenced Documents*\n`;
    docIds.slice(0, 10).forEach(id => {
      refs += `• \`${id}\`\n`;
    });

    if (docIds.length > 10) {
      refs += `\n_...and ${docIds.length - 10} more_`;
    }

    blocks.push({
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": refs
      }
    });
  }
}

// Footer
blocks.push({
  "type": "context",
  "elements": [{
    "type": "mrkdwn",
    "text": `⚡ Generated ${new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`
  }]
});

return {
  json: {
    channel: channel,
    blocks: blocks,
    text: `${query.substring(0, 50)}...\n${answer.substring(0, 100)}...`,
    thread_ts: thread_ts
  }
};

// ===================================
// Fetch Document Details Node
// Detects document references and prepares search
// ===================================

const agentOutput = $input.item.json;
const query = $('Process Event1').item.json.query || agentOutput.query || '';
const channel = $('Process Event1').item.json.channel || agentOutput.channel;
const thread_ts = $('Process Event1').item.json.thread_ts || agentOutput.thread_ts;
const aiResponse = agentOutput.output || agentOutput.text || '';

// Extract document IDs mentioned in AI response
const docIdPattern = /BMS[\-\u2011][A-Z]+[\-\u2011][A-Z]+[\-\u2011]\d+/g;
const mentionedDocs = aiResponse.match(docIdPattern) || [];

// Only fetch if AI mentioned documents
if (mentionedDocs.length > 0 && query.length > 0) {
  console.log(`📚 Found ${mentionedDocs.length} document references, fetching details...`);

  return {
    json: {
      // Pass through everything from agent
      ...agentOutput,

      // Add search parameters to fetch document details
      fetch_documents: true,
      search_query: query,
      limit: 5,
      score_threshold: 0.3,

      // CRITICAL: Preserve Slack metadata
      channel: channel,
      thread_ts: thread_ts
    }
  };
} else {
  console.log('ℹ️ No documents to fetch or empty query');

  return {
    json: {
      ...agentOutput,
      fetch_documents: false,
      query: query,
      channel: channel,
      thread_ts: thread_ts
    }
  };
}

// ===================================
// Merge Search Results Node
// Combines AI output with search API results
// ===================================

// Get data from previous HTTP call
const searchData = $input.item.json;

// Get agent data from earlier node
const agentData = $('Fetch Document Details').item.json;

// Extract search results
let documentDetails = [];

if (searchData && searchData.results && Array.isArray(searchData.results)) {
  documentDetails = searchData.results.slice(0, 5);
  console.log(`📊 Merged ${documentDetails.length} document results`);
} else if (searchData && searchData.chunks && Array.isArray(searchData.chunks)) {
  // Alternative response format
  documentDetails = searchData.chunks.slice(0, 5);
}

// Merge everything together
return {
  json: {
    // Agent output (AI response, query, etc.)
    output: agentData.output || agentData.text || '',
    query: agentData.query || agentData.search_query || $('Process Event1').item.json.query || '',

    // Document details from search
    search_results: documentDetails,
    total_results: documentDetails.length,

    // Pass through Slack metadata
    channel: agentData.channel || $('Process Event1').item.json.channel,
    thread_ts: agentData.thread_ts || $('Process Event1').item.json.thread_ts
  }
};
